script:
const payload = bh.input.body;

// ========================================
// Mandatory Validations
// ========================================

// Applicant Name
if (!payload.applicant_name || payload.applicant_name.trim() === '') {
    throw new Error("Applicant Name is required");
}

// DOB
if (!payload.dob) {
    throw new Error("Date of Birth is required");
}

// Age
if (!payload.age) {
    throw new Error("Age is required");
}

if (payload.age < 18 || payload.age > 65) {
    throw new Error("Age must be between 18 and 65");
}

// Mobile
const mobileRegex = /^[0-9]{10}$/;

if (!payload.mobile || !mobileRegex.test(String(payload.mobile))) {
    throw new Error("Mobile number must be exactly 10 digits");
}

// Email
if (
    !payload.email ||
    payload.email.indexOf('@') === -1 ||
    payload.email.indexOf('.') === -1
) {
    throw new Error("Invalid email format");
}

// Plan Type
if (!payload.plan_type) {
    throw new Error("Plan Type is required");
}

// Policy Term
if (!payload.policy_term) {
    throw new Error("Policy Term is required");
}

// Sum Insured
if (!payload.sum_insured || payload.sum_insured <= 0) {
    throw new Error("Sum Insured must be greater than 0");
}

// ========================================
// Prepare Payload For Data Service
// ========================================

bh.local.applicationData = {
    policy_applications: {
        applicant_name: payload.applicant_name,
        dob: payload.dob,
        age: payload.age,
        gender: payload.gender || null,
        mobile: payload.mobile,
        email: payload.email,
        address: payload.address || null,
        plan_type: payload.plan_type,
        sum_insured: payload.sum_insured,
        policy_term: payload.policy_term,
        medical_conditions: payload.medical_conditions || {},
        status: "DRAFT",
        assigned_role: "CUSTOMER"
    }
};

bh.local.response = {
    success: true,
    applicationId:
        bh.local.applicationDataResponse.payload.application_id,
    status:
        bh.local.applicationDataResponse.payload.status,
    assignedRole:
        bh.local.applicationDataResponse.payload.assigned_role,
    message: "Application saved successfully"
};

const payload = bh.input.body;

if (!payload.application_id) {
    throw new Error("Application Id is required");
}

bh.local.updatePayload = {
    policy_applications: {
        application_id: payload.application_id,
        applicant_name: payload.applicant_name,
        dob: payload.dob,
        age: payload.age,
        gender: payload.gender || null,
        mobile: payload.mobile,
        email: payload.email,
        address: payload.address || null,
        plan_type: payload.plan_type,
        sum_insured: payload.sum_insured,
        policy_term: payload.policy_term,
        medical_conditions: payload.medical_conditions || {},
        updated_at: new Date()
    }
};

console.log(
    "Update Payload:",
    JSON.stringify(bh.local.updatePayload, null, 2)
);

console.log(
    "UPDATE RESPONSE =>",
    JSON.stringify(
        bh.local.updateApplicationResponse,
        null,
        2
    )
);

if (
    !bh.local.updateApplicationResponse ||
    !bh.local.updateApplicationResponse.payload ||
    !bh.local.updateApplicationResponse.payload.application_id
) {
    throw new Error(
        "Application not found or cannot be updated"
    );
}

bh.local.response = {
    success: true,
    applicationId:
        bh.local.updateApplicationResponse.payload.application_id,
    message: "Application updated successfully"
};

const payload = bh.input.body;

if (!payload.application_id) {
    throw new Error("Application Id is required");
}

bh.local.submitPayload = {
    policy_applications: {
        application_id: payload.application_id,
        status: "SUBMITTED",
        assigned_role: "CASE_MANAGER",
        updated_at: new Date()
    }
};

console.log(
    "Submit Payload:",
    JSON.stringify(bh.local.submitPayload, null, 2)
);

console.log(
    "SUBMIT RESPONSE =>",
    JSON.stringify(
        bh.local.submitApplicationResponse,
        null,
        2
    )
);

if (
    !bh.local.submitApplicationResponse ||
    !bh.local.submitApplicationResponse.payload ||
    !bh.local.submitApplicationResponse.payload.application_id
) {
    throw new Error(
        "Application not found or already submitted"
    );
}

const applicationId =
    bh.local.submitApplicationResponse.payload.application_id;

bh.local.auditPayload = {
    policy_workflow_audit: {
        application_id: applicationId,
        previous_status: "DRAFT",
        current_status: "SUBMITTED",
        action_role: "CUSTOMER",
        remarks: "Application Submitted"
    }
};

console.log(
    "Audit Payload:",
    JSON.stringify(
        bh.local.auditPayload,
        null,
        2
    )
);

bh.local.response = {
    success: true,
    applicationId:
        bh.local.submitApplicationResponse.payload.application_id,
    status: "SUBMITTED",
    assignedRole: "CASE_MANAGER",
    message: "Application submitted successfully"
};

const applicationId =
    bh.input.params.applicationId;

if (!applicationId) {
    throw new Error("Application Id is required");
}

bh.local.findPayload = {
    filter: {
        application_id: applicationId
    }
};

if (
    !bh.local.applicationResponse ||
    !bh.local.applicationResponse.payload
) {
    throw new Error("Application not found");
}

bh.local.response = {
    success: true,
    data: bh.local.applicationResponse.payload
};

const payload = bh.input.body;

if (!payload.application_id) {
    throw new Error("Application Id is required");
}

bh.local.findPayload = {
    filter: {
        application_id: payload.application_id
    }
};

bh.local.response = {
    success: true,
    applicationId:
        bh.local.applicationResponse.payload.application_id,
    policyNumber:
        bh.local.policyNumber,
    status: "POLICY_ISSUED",
    message: "Policy generated successfully"
};

if (
    !bh.local.applicationResponse ||
    !bh.local.applicationResponse.payload
) {
    throw new Error("Application not found");
}

const app =
    bh.local.applicationResponse.payload;

// Prevent duplicate generation
if (app.status === "POLICY_ISSUED") {
    throw new Error(
        "Policy already generated for this application"
    );
}

// Premium validation
if (
    app.final_premium === null ||
    app.final_premium === undefined
) {
    throw new Error(
        "Final premium is not calculated"
    );
}

// Status validation
if (
    app.status !== "SUBMITTED" &&
    app.status !== "APPROVED"
) {
    throw new Error(
        "Application is not eligible for policy generation"
    );
}

const policyNumber =
    "POL" + Date.now();

bh.local.policyNumber = policyNumber;

bh.local.policyPayload = {
    policy_master: {
        policy_number: policyNumber,
        application_id: app.application_id,
        applicant_name: app.applicant_name,
        plan_type: app.plan_type,
        policy_term: Number(app.policy_term),
        sum_insured: Number(app.sum_insured),
        final_premium: Number(app.final_premium),
        issue_date: new Date(),
        status: "POLICY_ISSUED"
    }
};

console.log(
    "POLICY PAYLOAD =>",
    JSON.stringify(
        bh.local.policyPayload,
        null,
        2
    )
);

const app =
    bh.local.applicationResponse.payload;

bh.local.auditPayload = {
    policy_workflow_audit: {
        application_id: app.application_id,
        previous_status: app.status,
        current_status: "POLICY_ISSUED",
        action_role: "UNDERWRITER",
        remarks: "Policy Generated"
    }
};

let message = "Failed to create application";
let statusCode = 500;

if (bh.error) {

    message =
        bh.error.message ||
        bh.error.toString() ||
        message;

    // Validation Errors
    if (
        message.includes("Applicant Name") ||
        message.includes("Date of Birth") ||
        message.includes("Age") ||
        message.includes("Mobile") ||
        message.includes("Email") ||
        message.includes("Plan Type") ||
        message.includes("Policy Term") ||
        message.includes("Sum Insured")
    ) {
        statusCode = 400;
    }

    // HTTP / Integration Errors
    else if (message.includes("404")) {
        message = "Data service endpoint not found";
        statusCode = 502;
    }

    else if (
        message.includes("ECONNREFUSED") ||
        message.includes("connect ECONNREFUSED")
    ) {
        message = "Data service is unavailable";
        statusCode = 503;
    }

    else if (
        message.includes("Response code") ||
        message.includes("Bad Request") ||
        message.includes("must be object")
    ) {
        message = "Invalid request sent to data service";
        statusCode = 400;
    }
}

bh.local.statusCode = statusCode;

bh.local.apiResponse = {
    success: false,
    api: "createApplication",
    message: message
};

console.error(
    "CREATE APPLICATION ERROR:",
    bh.error
);

let message = "Failed to update application";
let statusCode = 500;

if (bh.error) {

    message =
        bh.error.message ||
        bh.error.toString() ||
        message;

    // Validation Errors
    if (
        message.includes("Application Id") ||
        message.includes("Application not found")
    ) {
        statusCode = 400;
    }

    // HTTP / Integration Errors
    else if (message.includes("404")) {
        message = "Data service endpoint not found";
        statusCode = 502;
    }

    else if (
        message.includes("ECONNREFUSED") ||
        message.includes("connect ECONNREFUSED")
    ) {
        message = "Data service is unavailable";
        statusCode = 503;
    }

    else if (
        message.includes("Response code") ||
        message.includes("Bad Request") ||
        message.includes("must be object")
    ) {
        message = "Invalid request sent to data service";
        statusCode = 400;
    }
}

bh.local.statusCode = statusCode;

bh.local.apiResponse = {
    success: false,
    api: "updateApplication",
    message: message
};

console.error(
    "UPDATE APPLICATION ERROR:",
    bh.error
);

let message = "Failed to submit application";
let statusCode = 500;

if (bh.error) {

    message =
        bh.error.message ||
        bh.error.toString() ||
        message;

    // Validation Errors
    if (
        message.includes("Application Id") ||
        message.includes("Application not found")
    ) {
        statusCode = 400;
    }

    // Endpoint Not Found
    else if (message.includes("404")) {
        message = "Data service endpoint not found";
        statusCode = 502;
    }

    // Service Down
    else if (
        message.includes("ECONNREFUSED") ||
        message.includes("connect ECONNREFUSED")
    ) {
        message = "Data service is unavailable";
        statusCode = 503;
    }

    // Invalid Payload
    else if (
        message.includes("Response code") ||
        message.includes("Bad Request") ||
        message.includes("must be object")
    ) {
        message = "Invalid request sent to data service";
        statusCode = 400;
    }

    // Internal Data Service Error
    else if (
        message.includes("500") ||
        message.includes("Internal Server Error")
    ) {
        message = "Data service processing failed";
        statusCode = 500;
    }
}

bh.local.statusCode = statusCode;

bh.local.apiResponse = {
    success: false,
    api: "submitApplication",
    message: message
};

console.error(
    "SUBMIT APPLICATION ERROR:",
    bh.error
);

let message =
    "Failed to fetch application details";
let statusCode = 500;

if (bh.error) {

    message =
        bh.error.message ||
        bh.error.toString() ||
        message;

    if (
        message.includes("Application Id") ||
        message.includes("Application not found")
    ) {
        statusCode = 404;
    }

    else if (message.includes("404")) {
        message = "Data service endpoint not found";
        statusCode = 502;
    }

    else if (
        message.includes("ECONNREFUSED") ||
        message.includes("connect ECONNREFUSED")
    ) {
        message = "Data service is unavailable";
        statusCode = 503;
    }

    else if (
        message.includes("Response code") ||
        message.includes("Bad Request") ||
        message.includes("must be object")
    ) {
        message = "Invalid request sent to data service";
        statusCode = 400;
    }
}

bh.local.statusCode = statusCode;

bh.local.apiResponse = {
    success: false,
    api: "getApplicationDetails",
    message: message
};

console.error(
    "GET APPLICATION DETAILS ERROR:",
    bh.error
);

let message = "Failed to generate policy";
let statusCode = 500;

if (bh.error) {

    message =
        bh.error.message ||
        bh.error.toString() ||
        message;

    if (
        message.includes("Application Id") ||
        message.includes("Application not found") ||
        message.includes("Policy already generated") ||
        message.includes("Final premium is not calculated") ||
        message.includes("eligible for policy generation")
    ) {
        statusCode = 400;
    }

    else if (message.includes("404")) {
        message = "Data service endpoint not found";
        statusCode = 502;
    }

    else if (
        message.includes("ECONNREFUSED") ||
        message.includes("connect ECONNREFUSED")
    ) {
        message = "Data service is unavailable";
        statusCode = 503;
    }

    else if (
        message.includes("Response code") ||
        message.includes("Bad Request") ||
        message.includes("must be object")
    ) {
        message = "Invalid request sent to data service";
        statusCode = 400;
    }
}

bh.local.statusCode = statusCode;

bh.local.apiResponse = {
    success: false,
    api: "generatePolicy",
    message: message
};

console.error(
    "GENERATE POLICY ERROR:",
    bh.error
);
